      "question": "Which number shows the 'Expanded Form' of 9999?",
      "options": [
        "9000 + 900 + 90 + 9",
        "9 + 90 + 900 + 9000",
        "999 + 9"
      ],
      "correct_index": 0,
      "explanation": "The 'Expanded Form' of a number shows the value of each digit added together, starting from the largest place value.",
      "selected_because": "the lesson showed the expanded form of 9999",
      "distractor_misconceptions": {
        "1": "believes order of addition matters for expanded form",
        "2": "confuses expanded form with partial sums"
      },
      "option_feedback": {
        "correct": "That's right! The 'Expanded Form' shows the value of each digit, like 9 Thousands, 9 Hundreds, 9 Tens, and 9 Ones.",
        "wrong": {
          "1": "You have the right numbers, but the 'Expanded Form' usually starts with the largest place value. Remember, addition order doesn't change the total, but we write expanded form in a specific way.",
          "2": "This shows part of the number, but 'Expanded Form' means breaking down the number by the 'Place Value' of each 'Digit'. For 9999, it's 9000 + 900 + 90 + 9."
        }
      },
